  9	export default function useDebouncedFunction() {
 10	    const cache = useCache<string, CacheValue>();
 11	
 12	    /**
 13	     * Return already existing promise for the same call.
 14	     *
 15	     * In the case two callers depend on the same promise, the promise is
 16	     * aborted only when all signals are aborted. If one caller does not
 17	     * provide signal, it is never aborted to respect the callers choice.
 18	     */
 19	    const debouncedFunction = <T>(
 20	        callback: (signal: AbortSignal) => Promise<T>,
 21	        args: object,
 22	        signal?: AbortSignal
 23	    ): Promise<T> => {
 24	        const key = `drivedebouncedfn_${JSON.stringify(args)}`;
 25	        const cachedValue = cache.get(key);
 26	
 27	        // When signal is aborted, it can take a bit of time before the promise
 28	        // is removed from the cache. Therefore it is better to double check.
 29	        if (cachedValue && !cachedValue.controller.signal.aborted) {
 30	            cachedValue.signals.push(signal);
 31	            addAbortListener(cachedValue, signal);
 32	            return propagateAbortError(cachedValue.promise, signal);
 33	        }
 34	
 35	        const controller = new AbortController();
 36	        const promise = callback(controller.signal);
 37	
 38	        const value = {
 39	            promise,
 40	            controller,
 41	            signals: [signal],
 42	        };
 43	        cache.set(key, value);
 44	        addAbortListener(value, signal);
 45	
 46	        const cleanup = () => {
 47	            cache.delete(key);
 48	        };
 49	        promise.then(cleanup).catch(cleanup);
 50	        return propagateAbortError(promise, signal);
 51	    };
 52	
 53	    return debouncedFunction;
 54	}
