 56	function addAbortListener(value: CacheValue, signal?: AbortSignal) {
 57	    if (!signal) {
 58	        return;
 59	    }
 60	    const handleAbort = () => {
 61	        const allAborted = !value.signals.some((signal) => !signal || !signal.aborted);
 62	        if (allAborted) {
 63	            value.controller.abort();
 64	        }
 65	    };
 66	    signal.addEventListener('abort', handleAbort);
 67	    value.promise.finally(() => {
 68	        signal.removeEventListener('abort', handleAbort);
 69	    });
 70	}
