 72	function propagateAbortError<T>(promise: Promise<T>, signal?: AbortSignal): Promise<T> {
 73	    return promise.then((result: T) => {
 74	        // The original signal is wrapped, so the check if aborted error
 75	        // should be propagated needs to be done.
 76	        if (signal?.aborted) {
 77	            // Replace with throw signal.reason once supported by browsers.
 78	            throw new DOMException('Aborted', 'AbortError');
 79	        }
 80	        return result;
 81	    });
